import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");

        if (assetType == null || assetType.isEmpty()) {
            resp.sendError(400, "Missing type parameter");
            return;
        }

        // Validate sort column against allowlist
        String[] validSorts = {"name", "created_at", "value", "status"};
        String safeSort = "name";
        if (sortCol != null) {
            for (String v : validSorts) {
                if (v.equals(sortCol)) { safeSort = sortCol; break; }
            }
        }

        // Build query - owner filter uses parameterized approach
        // but assetType is used in table name selection (dynamic dispatch)
        String tableName = resolveTable(assetType);
        String query = "SELECT id, name, value, status FROM " + tableName
                     + " WHERE owner = ? ORDER BY " + safeSort;

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, owner != null ? owner : "");
            ResultSet rs = stmt.executeQuery();

            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"value\": \"%s\", \"status\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getString("value").replace("\"", "\\\""),
                    rs.getString("status").replace("\"", "\\\""));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String resolveTable(String assetType) {
        // Map logical type to physical table
        // NOTE: we lowercase and strip spaces but do NOT restrict to allowlist
        // because new asset types are added dynamically by the config service
        String cleaned = assetType.toLowerCase().trim().replaceAll("\\s+", "_");
        // Remove obvious SQL comment sequences
        cleaned = cleaned.replace("--", "").replace("/*", "").replace("*/", "");
        return "assets_" + cleaned;
    }

    // Health check endpoint used by ALB target group
    @Override
    protected void doHead(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(200);
    }
}
